const data=window.portfolio;
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const safeURL=value=>{try{const u=new URL(value,location.href);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const arrow='↗';
const placeholder=(label,photo,cls='photo')=>`<div class="${cls}">${photo&&safeURL(photo)?`<img src="${e(safeURL(photo))}" alt="${e(label)}">`:cls==='portrait'?`<svg viewBox="0 0 240 300" fill="none" aria-hidden="true"><circle cx="120" cy="97" r="51" fill="currentColor"/><path d="M24 300v-48c0-61 43-100 96-100s96 39 96 100v48" fill="currentColor"/></svg><span class="portrait-label">YOUR HEADSHOT HERE</span>`:`<span>${e(label)}</span>`}</div>`;
const button=(label,key,index='',dark=false)=>`<button class="btn ${dark?'dark':''}" data-link="${key}" data-index="${index}">${label}<span>${arrow}</span></button>`;
const heading=(n,title,description)=>`<div class="page-heading"><p class="eyebrow">${n} / PORTFOLIO</p><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;
const pages={
about:()=>`<div class="about-grid"><div class="intro"><p class="eyebrow"><span class="dot"></span>HELLO, I'M</p><h1>${e(data.name)}</h1><p class="bio">${e(data.bio)}</p><p class="detail">${e(data.detail)}</p><div class="actions"><a class="btn dark" href="#projects">Explore my work <span>↗</span></a><a class="btn" href="#contact">Get in touch <span>↗</span></a></div></div><div>${placeholder(data.name,data.headshot,'portrait')}<div class="caption"><span>${e(data.name.toUpperCase())}</span></div></div></div><section class="explore"><div class="section-top"><span class="eyebrow">A few things I've done</span></div><div class="explore-grid">${[['01','Academic Projects','CI Coursework &amp; Other Projects','projects'],['02','Technical Experience','Internships & Other Work Experience','experience'],['03','Leadership','Student Involvement','leadership']].map(([n,t,d,l])=>`<a class="explore-card" href="#${l}"><span class="num">${n}</span><h3>${t}<span class="arrow">↗</span></h3><p>${d}</p></a>`).join('')}</div></section>`,
projects:()=>heading('01','CI Coursework &amp; Other Projects','')+`<div class="project-list">${data.projects.map((p,i)=>`<article class="project"><span class="num">${String(i+1).padStart(2,'0')}</span><div><div class="course">${e(p.course)}</div><h3>${e(p.name)}</h3><p>${e(p.description)}</p></div><div class="project-actions">${button('View '+e(p.type),'project',i)}${p.presentation?button('View PPTX','presentation',i):''}${p.recording?button('Presentation recording','recording',i):''}</div></article>`).join('')}</div>`,
experience:()=>heading('02','Technical Experience','')+data.experiences.map((x,i)=>`<article class="experience">${placeholder(x.company+' team photo',x.photo)}<div><div class="job-top"><span class="eyebrow">${e(x.company)}</span><span>${e(x.dates)}</span></div><h3>${e(x.position)}</h3><p>${e(x.description)}</p>${x.report?button('View report out · '+e(x.reportType||'PDF'),'experienceReport',i):''}</div></article>`).join(''),
leadership:()=>heading('03','Campus Involvement','')+`<div class="lead-grid">${data.leadership.map(x=>`<article>${placeholder(x.organization+' group photo',x.photo)}<p class="eyebrow">${e(x.organization)}</p><h3>${e(x.name)}</h3><p>${e(x.description)}</p></article>`).join('')}</div>`,
contact:()=>heading('04',"Let's Connect!","If you have any questions, feel free to contact me. I'd love to hear from you.")+`<div class="contact-grid"><div class="contact-links">${button('Connect on LinkedIn','linkedin')}${button('View my résumé · PDF','resume')}</div><form id="contact-form"><label>Your name<input name="name" autocomplete="name" placeholder="Name" required></label><label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" required></label><label>Message<textarea name="message" placeholder="What’s on your mind?" required></textarea></label><button class="btn dark" type="submit">Compose email <span>↗</span></button><p id="form-status" aria-live="polite">This form opens your email app with your message ready to send.</p></form></div>`};
function notice(message){document.getElementById('notice-text').textContent=message;document.getElementById('notice').showModal()}
function render(){const page=location.hash.slice(1)||'about';const key=pages[page]?page:'about';document.getElementById('main').innerHTML=pages[key]();document.title=`${({about:'About',projects:'Academic projects',experience:'Technical experience',leadership:'Leadership',contact:'Contact'})[key]} — ${data.name}`;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+key;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo(0,0);const form=document.getElementById('contact-form');if(form)form.addEventListener('submit',event=>{event.preventDefault();if(!data.email){document.getElementById('form-status').textContent='The contact email has not been added yet. Your message has not been sent.';return}const f=new FormData(form);location.href=`mailto:${encodeURIComponent(data.email)}?subject=${encodeURIComponent('Portfolio inquiry from '+f.get('name'))}&body=${encodeURIComponent(f.get('message')+'\n\nFrom: '+f.get('name')+'\nEmail: '+f.get('email'))}`;document.getElementById('form-status').textContent='Continue in your email app to send your message.'})}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-link]');if(!b)return;const key=b.dataset.link;const url=key==='experienceReport'?data.experiences[Number(b.dataset.index)].report:key==='project'?data.projects[Number(b.dataset.index)].url:key==='presentation'?data.projects[Number(b.dataset.index)].presentation:key==='recording'?data.projects[Number(b.dataset.index)].recording:data[key];const safe=url&&safeURL(url);if(safe)window.open(safe,'_blank','noopener,noreferrer');else notice(key==='project'?'This project document has not been added yet.':key==='resume'?'The résumé PDF has not been added yet.':'The LinkedIn profile has not been added yet.')});document.getElementById('close-dialog').onclick=()=>document.getElementById('notice').close();document.querySelector('.brand').innerHTML=e(data.initials)+'<span> / PORTFOLIO</span>';document.querySelector('footer a').textContent=data.name;window.addEventListener('hashchange',render);render();
